// KEVOS® WORKOS input guides: handbook5. What each input means, how to get it right and which figure explains it.
// Read with public/tools/input-guides.js; units, accepted ranges and examples come from data-handbook5.js.
window.WORKOS_INPUTS = Object.assign(window.WORKOS_INPUTS || {}, {
  'force-resultant': {
    F1: { what: 'The size of this force acting through the common point, from your load analysis, without its direction.', tip: 'Give the magnitude as a positive number and set its direction with the angle; a force of 0 is skipped.', fig: 'force', sym: 'F' },
    a1: { what: 'The direction this force acts in, measured anticlockwise from the positive X axis in the plane of the forces.', tip: 'Use one X axis for all forces. A clockwise direction can be entered as a negative angle.', fig: 'angle', sym: 'θ' },
    F2: { what: 'The size of this force acting through the common point, from your load analysis, without its direction.', tip: 'Give the magnitude as a positive number and set its direction with the angle; a force of 0 is skipped.', fig: 'force', sym: 'F' },
    a2: { what: 'The direction this force acts in, measured anticlockwise from the positive X axis in the plane of the forces.', tip: 'Use one X axis for all forces. A clockwise direction can be entered as a negative angle.', fig: 'angle', sym: 'θ' },
    F3: { what: 'The size of this force acting through the common point, from your load analysis, without its direction.', tip: 'Leave it at 0 when there is no third force; its angle is then ignored.', fig: 'force', sym: 'F' },
    a3: { what: 'The direction this force acts in, measured anticlockwise from the positive X axis in the plane of the forces.', tip: 'Ignored when the matching magnitude is 0.', fig: 'angle', sym: 'θ' },
    F4: { what: 'The size of this force acting through the common point, from your load analysis, without its direction.', tip: 'Leave it at 0 when there is no fourth force; its angle is then ignored.', fig: 'force', sym: 'F' },
    a4: { what: 'The direction this force acts in, measured anticlockwise from the positive X axis in the plane of the forces.', tip: 'Ignored when the matching magnitude is 0.', fig: 'angle', sym: 'θ' },
  },
  'inclined-plane': {
    mass: { what: 'The mass of everything that slides on the slope: the load plus any pallet, carrier or sled. The tool turns it into a weight using standard gravity.', tip: 'Enter mass in kg, not a weight in newtons.', effect: 'Every force result rises in proportion to the mass.', fig: 'mass', sym: 'm' },
    angle: { what: 'The slope of the plane, measured from horizontal: 0° is level and larger angles are steeper.', tip: 'Measure from horizontal, not from vertical. A slope given as a percentage or ratio must be converted to degrees first.', fig: 'angle', sym: 'θ' },
    mu: { what: 'The coefficient of friction between the load and the surface it slides on: friction force divided by the force pressing the surfaces together.', tip: 'Use the sliding (kinetic) value for steady movement and the static value for the force to start it moving; both come from tests or supplier data.', effect: 'Higher friction raises the force to push up and decides whether the load holds by itself on the slope.', fig: 'friction', sym: 'μ' },
  },
  'flywheel-energy': {
    mass: { what: 'The mass of the rotating disc or rim whose inertia stores the energy, by weighing or from the CAD model.', tip: 'Hub, spokes and shaft are not counted unless their mass is included here, and the tool treats all of it as a uniform disc or ring.', effect: 'The moment of inertia and the energy released rise in proportion to the mass.', fig: 'mass', sym: 'm' },
    outer: { what: 'The outside diameter of the flywheel, across the rim through the centre. It sets the inertia and the rim speed.', tip: 'Use the diameter, not the radius.', effect: 'Inertia rises with the square of the diameter, and rim speed rises in proportion to it.', fig: 'diameter', sym: 'D' },
    inner: { what: 'The inside diameter of a ring-shaped rim, for a flywheel whose mass sits in a ring. Zero treats it as a uniform solid disc.', tip: 'It must be smaller than the outer diameter.', fig: 'diameter', sym: 'd' },
    nmax: { what: 'The flywheel speed at the start of the energy draw, for example just before a press stroke or punch begins. The rim speed is checked at this speed.', tip: 'It must be higher than the minimum speed.', fig: 'rotation', sym: 'n₁' },
    nmin: { what: 'The lowest speed the flywheel is allowed to fall to during the working stroke, before the motor brings it back up.', tip: 'The energy released depends on the difference of the squared speeds, so a small change in this speed changes the result noticeably.', fig: 'rotation', sym: 'n₂' },
    vmax: { what: 'The highest rim speed the flywheel is allowed to run at, from the maker or your design standard for its material and construction. The tool compares the calculated rim speed with it.', tip: 'This limit is not calculated by the tool; it must come from the maker or a stress analysis.', fig: 'velocity' },
  },
  'centrifugal-force': {
    mass: { what: 'The mass of the rotating part whose outward pull you want, such as a chuck jaw, counterweight or blade.', tip: 'Include the screws and fittings that move with the part.', effect: 'The force rises in proportion to the mass.', fig: 'mass', sym: 'm' },
    radius: { what: 'The distance from the rotation axis to the part’s own centre of mass, not to its outer edge.', tip: 'Use the radius, not the diameter of the circle the part runs on.', effect: 'The force rises in proportion to the radius.', fig: 'radius', sym: 'r' },
    rpm: { what: 'The rotational speed of the part, normally the highest speed it will run at in service.', tip: 'Use the maximum possible speed, including any overspeed, not the usual running speed.', effect: 'The force rises with the square of the speed, so doubling the speed gives four times the force.', fig: 'rotation', sym: 'n' },
  },
  'balance-grade': {
    mass: { what: 'The mass of the complete rotating assembly being balanced: the rotor with everything that turns with it.', tip: 'Include fitted parts such as pulleys or fans if they are balanced with the rotor.', effect: 'The permissible residual unbalance rises in proportion to the mass.', fig: 'mass', sym: 'M' },
    rpm: { what: 'The highest speed at which the rotor runs in service, which sets how tight the balance must be.', tip: 'Use the maximum service speed, not the speed of the balancing machine.', effect: 'A higher speed lowers the permissible unbalance in proportion.', fig: 'rotation', sym: 'n' },
    grade: { what: 'The balance quality grade (G number) the rotor must meet. A smaller G number means a tighter balance requirement.', tip: 'Take the grade from the equipment standard, purchase specification or ISO 21940-11 for the machine type.', effect: 'The permissible unbalance rises in proportion to the G number.', fig: 'choice', sym: 'G' },
    planes: { what: 'Whether the unbalance is corrected in one plane, for a narrow disc, or in two planes, for a longer rotor. With two planes the tool gives each plane half of the total.', tip: 'The equal split is valid only when the centre of mass lies midway between the planes; otherwise use the standard’s allocation rules.', fig: 'choice' },
    measured: { what: 'The residual unbalance left in each correction plane after balancing, as reported by the balancing machine. Zero means no measurement has been entered.', tip: 'Enter the value per plane in g·mm; the tool compares it with the permissible value per plane.', fig: 'number', sym: 'U' },
  },
  'impact-load': {
    mode: { what: 'Whether the body falls onto the stop from a height, or moves horizontally into the stop at a known speed.', tip: 'Only the input for the chosen situation is used: drop height for falling, speed for moving.', fig: 'choice' },
    mass: { what: 'The mass of the body that hits the stop and must be brought to rest.', tip: 'Include everything that moves with the body, such as a carriage, fixture or load.', effect: 'The energy and stopping force rise in proportion to the mass.', fig: 'mass', sym: 'm' },
    height: { what: 'How far the body falls freely before it first touches the stop. Used only for a falling mass.', tip: 'Measure to first contact; the tool adds the fall through the stopping distance itself.', fig: 'height', sym: 'h' },
    speed: { what: 'The speed of the body at the moment it first touches the stop. Used only for a moving mass.', tip: 'Use the real speed at contact, which may be higher than the nominal conveyor or axis speed.', effect: 'The energy rises with the square of the speed.', fig: 'velocity', sym: 'v' },
    stop: { what: 'The distance over which the body is brought to rest after contact: the buffer or shock absorber stroke, spring deflection or crush depth.', tip: 'A small error here matters: halving the stopping distance roughly doubles the stopping force.', effect: 'The average and peak stopping forces fall as the stopping distance increases.', fig: 'length', sym: 's' },
  },
  'move-profile': {
    distance: { what: 'The length of one point-to-point move, from start position to end position.', tip: 'Use the actual travel of the axis or conveyor, not the stroke of the whole machine.', fig: 'length', sym: 'L' },
    vmax: { what: 'The highest speed the axis is allowed to reach during the move, set by the drive, the mechanism or the process.', tip: 'If the move is too short, the axis never reaches this speed and the tool reports a triangular profile.', fig: 'velocity', sym: 'v' },
    accel: { what: 'The rate at which the axis speeds up at the start and slows down at the end; the tool uses the same value for both.', tip: 'Enter mm/s², not m/s²: 1 m/s² is 1000 mm/s².', effect: 'Higher acceleration shortens the move time and raises the acceleration force in proportion.', fig: 'acceleration', sym: 'a' },
    mass: { what: 'The total mass the drive must accelerate: carriage, tooling, gripper and product together. It is used only for the acceleration force.', tip: 'The force shown excludes friction, gravity on vertical axes and process forces; add them before sizing a drive.', effect: 'The acceleration force rises in proportion to the mass; the move time does not change.', fig: 'mass', sym: 'm' },
  },
  'sling-tension': {
    mass: { what: 'The total mass hanging below the hook: the load plus lifting beams, shackles and other attachments.', tip: 'Use a confirmed mass, for example from a weighbridge or the maker’s data, not an estimate.', effect: 'The tension in each leg rises in proportion to the mass.', fig: 'mass', sym: 'm' },
    legs: { what: 'The number of sling legs that are assumed to share the load equally.', tip: 'Many lifting codes count only two legs of a three- or four-leg sling unless load sharing is assured; follow your code.', effect: 'More sharing legs lower the tension per leg.', fig: 'count', sym: 'n' },
    angle: { what: 'The angle of each sling leg measured from vertical, which is half the included angle between two legs.', tip: 'Do not enter the included angle between legs or the angle from horizontal.', effect: 'Leg tension rises steeply as the angle from vertical increases.', fig: 'angle', sym: 'β' },
    wll: { what: 'The working load limit of one sling leg in a straight vertical pull, as marked on the sling tag. The tool compares each leg’s tension with it.', tip: 'Use the single-leg vertical rating from the tag, not the rating of the whole sling assembly at an angle.', fig: 'mass' },
  },
  'combined-cg': {
    m1: { what: 'The mass of this item in the assembly, from weighing or the CAD model. Items left at zero are not included.', tip: 'Use the same mass unit for every item; the result is a mass-weighted average.', fig: 'mass', sym: 'm' },
    x1: { what: 'The X coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Use one datum and one set of axis directions for every item; a coordinate on the other side of the datum is negative.', fig: 'length', sym: 'x' },
    y1: { what: 'The Y coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Keep the sign of the coordinate; mixing directions moves the combined centre of gravity.', fig: 'length', sym: 'y' },
    z1: { what: 'The Z coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'If Z is height, measure all items from the same base level.', fig: 'height', sym: 'z' },
    m2: { what: 'The mass of this item in the assembly, from weighing or the CAD model. Items left at zero are not included.', tip: 'Use the same mass unit for every item; the result is a mass-weighted average.', fig: 'mass', sym: 'm' },
    x2: { what: 'The X coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Use one datum and one set of axis directions for every item; a coordinate on the other side of the datum is negative.', fig: 'length', sym: 'x' },
    y2: { what: 'The Y coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Keep the sign of the coordinate; mixing directions moves the combined centre of gravity.', fig: 'length', sym: 'y' },
    z2: { what: 'The Z coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'If Z is height, measure all items from the same base level.', fig: 'height', sym: 'z' },
    m3: { what: 'The mass of this item in the assembly, from weighing or the CAD model. Items left at zero are not included.', tip: 'Use the same mass unit for every item; the result is a mass-weighted average.', fig: 'mass', sym: 'm' },
    x3: { what: 'The X coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Use one datum and one set of axis directions for every item; a coordinate on the other side of the datum is negative.', fig: 'length', sym: 'x' },
    y3: { what: 'The Y coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Keep the sign of the coordinate; mixing directions moves the combined centre of gravity.', fig: 'length', sym: 'y' },
    z3: { what: 'The Z coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'If Z is height, measure all items from the same base level.', fig: 'height', sym: 'z' },
    m4: { what: 'The mass of this item in the assembly, from weighing or the CAD model. Items left at zero are not included.', tip: 'Use the same mass unit for every item; the result is a mass-weighted average.', fig: 'mass', sym: 'm' },
    x4: { what: 'The X coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Use one datum and one set of axis directions for every item; a coordinate on the other side of the datum is negative.', fig: 'length', sym: 'x' },
    y4: { what: 'The Y coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Keep the sign of the coordinate; mixing directions moves the combined centre of gravity.', fig: 'length', sym: 'y' },
    z4: { what: 'The Z coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'If Z is height, measure all items from the same base level.', fig: 'height', sym: 'z' },
    m5: { what: 'The mass of this item in the assembly, from weighing or the CAD model. Items left at zero are not included.', tip: 'Use the same mass unit for every item; the result is a mass-weighted average.', fig: 'mass', sym: 'm' },
    x5: { what: 'The X coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Use one datum and one set of axis directions for every item; a coordinate on the other side of the datum is negative.', fig: 'length', sym: 'x' },
    y5: { what: 'The Y coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'Keep the sign of the coordinate; mixing directions moves the combined centre of gravity.', fig: 'length', sym: 'y' },
    z5: { what: 'The Z coordinate of this item’s own centre of gravity, measured from the datum shared by all items.', tip: 'If Z is height, measure all items from the same base level.', fig: 'height', sym: 'z' },
  },
  'mass-moment-inertia': {
    shape: { what: 'The idealised body shape and the axis it turns about, which decides the formula and what dimensions A and B mean.', tip: 'For a complex part, CAD mass properties are more accurate than any of these idealised shapes.', fig: 'choice' },
    mass: { what: 'The mass of the body, by weighing or from the CAD model. The tool assumes it is spread evenly through the idealised shape.', tip: 'Holes and pockets change both the mass and how it is distributed.', effect: 'The moment of inertia rises in proportion to the mass.', fig: 'mass', sym: 'm' },
    dimA: { what: 'The main size of the body: the outer diameter of a disc, ring, cylinder or sphere, side a of a block, or the full length of a rod.', tip: 'Enter the diameter, not the radius, for round shapes; the tool halves it.', effect: 'The moment of inertia rises with the square of this dimension.', fig: 'diameter', sym: 'A' },
    dimB: { what: 'The second size of the body: the inner diameter of a ring, the length of a cylinder turning about an axis across it, or side b of a block.', tip: 'Not used for a disc, sphere or rod. For a ring it must be smaller than the outer diameter.', fig: 'length', sym: 'B' },
    offset: { what: 'The distance between the body’s own axis and the actual rotation axis when the two are parallel, for a body that turns off-centre. Zero if it turns about its own axis.', tip: 'The parallel-axis rule is exact only from an axis through the centre of mass; for the rod, whose formula is already about its end, leave it at 0.', effect: 'Adds the mass times the square of the offset to the moment of inertia.', fig: 'length', sym: 'd' },
  },
  'belt-friction': {
    slack: { what: 'The tension on the low-tension side of the belt, rope or band: the slack-side belt tension, the anchor force of a band brake, or the hand force holding a rope on a capstan.', tip: 'This is the smaller of the two tensions; the tool calculates the larger, tight-side tension from it.', effect: 'The tight-side tension rises in proportion to it.', fig: 'force', sym: 'T₂' },
    mu: { what: 'The coefficient of friction between the belt, rope or lining and the drum or pulley it wraps around.', tip: 'Take it from the supplier or tests and use a conservative value for wet, oily or worn surfaces.', effect: 'The tension ratio grows exponentially with friction times wrap angle, so small changes matter.', fig: 'friction', sym: 'μ' },
    wrap: { what: 'The angle of contact between the belt or rope and the drum, measured around the drum. Several full turns add 360° each.', tip: 'Enter degrees; for a rope with three turns on a capstan that is 3 × 360°.', effect: 'The tension ratio grows exponentially with the wrap angle.', fig: 'angle', sym: 'θ' },
    groove: { what: 'The included angle of a V-groove that the belt or rope wedges into. Zero means flat contact with no wedging.', tip: 'Use the full included angle of the groove, not the half angle. A V-groove raises the effective friction.', fig: 'angle', sym: 'β' },
  },
  'column-buckling': {
    E: { what: 'The elastic modulus (Young’s modulus) of the column material: its stiffness in tension and compression, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'E' },
    Sy: { what: 'The minimum yield strength of the column material, the stress at which it starts to deform permanently, from the material certificate or specification.', tip: 'Use the specified minimum, not a typical test value.', fig: 'stress', sym: 'Sy' },
    A: { what: 'The cross-section area of the column or strut, the area of material cut across its length, from a section table or a section properties calculation.', tip: 'Use the net area of the actual section, in mm².', fig: 'area', sym: 'A' },
    I: { what: 'The smallest second moment of area of the section, about its weak axis. It describes how the material is spread from that axis and resists bending sideways.', tip: 'Use the least value of the section; a column buckles about its weakest axis unless that direction is braced.', fig: 'section', sym: 'I' },
    L: { what: 'The length of the column between the points that are held against sideways movement.', tip: 'Measure between actual lateral supports, not the overall member length if it is braced partway.', effect: 'In the slender (Euler) range the buckling load falls with the square of the length.', fig: 'length', sym: 'L' },
    K: { what: 'The effective length factor: a multiplier on the unsupported length that accounts for how the ends are held (pinned, fixed or free).', tip: 'Design codes often use larger values than the theoretical ones for real end conditions; use your code’s value.', effect: 'A larger factor increases the slenderness and lowers the buckling load.', fig: 'factor', sym: 'K' },
    P: { what: 'The largest compressive axial load the member must carry along its length.', tip: 'Include all load cases that put the member in compression and use the largest.', effect: 'The safety factor falls in proportion as this load rises.', fig: 'force', sym: 'P' },
    req: { what: 'The minimum ratio of critical buckling load to applied load that the member must achieve, from your design code, customer specification or company standard.', tip: 'This is a requirement you set; the tool only compares the calculated factor with it.', fig: 'factor', sym: 'n' },
  },
  'principal-stress': {
    sx: { what: 'The normal stress acting in the X direction at the point being checked, from your stress calculation. Tension is positive and compression negative.', tip: 'Include stress concentration effects before entering it; the tool does not add them.', fig: 'stress', sym: 'σx' },
    sy: { what: 'The normal stress acting in the Y direction at the same point, at right angles to σx. Tension is positive and compression negative.', tip: 'Keep the sign: a compressive stress entered as positive changes every result.', fig: 'stress', sym: 'σy' },
    txy: { what: 'The shear stress acting on the X and Y faces of the same small element, for example from torsion or transverse shear.', tip: 'Its sign affects the principal angle but not the sizes of the principal stresses.', fig: 'stress', sym: 'τxy' },
    Sy: { what: 'The minimum yield strength of the material at the point being checked, from the material certificate or specification. The equivalent stresses are compared with it.', tip: 'Use the specified minimum, not a typical value.', fig: 'stress', sym: 'Sy' },
    req: { what: 'The minimum ratio of yield strength to equivalent stress the part must achieve, from your design code, customer specification or company standard.', tip: 'This is a requirement you set; the tool only compares the calculated factor with it.', fig: 'factor', sym: 'n' },
  },
  'pressure-cylinder': {
    di: { what: 'The bore of the tube, pipe or cylinder: the diameter of the inside surface that the pressure acts on.', tip: 'Use the inside diameter, not the outside diameter or nominal pipe size.', fig: 'diameter', sym: 'dᵢ' },
    t: { what: 'The wall thickness between the bore and the outside surface that carries the pressure.', tip: 'Use the minimum thickness after manufacturing tolerance, corrosion allowance and machining, not the nominal thickness.', effect: 'A thicker wall lowers the hoop stress and raises the safety factor.', fig: 'thickness', sym: 't' },
    p: { what: 'The internal pressure above the outside (atmospheric) pressure, at the maximum working or test condition.', tip: 'Enter gauge pressure in MPa: 1 MPa is 10 bar. Do not add atmospheric pressure.', effect: 'All stresses rise in proportion to the pressure, so the safety factor falls in proportion.', fig: 'pressure', sym: 'p' },
    ends: { what: 'Whether the pressure force on the end caps is carried by this wall (closed ends) or by something else such as tie rods or an external frame (open).', tip: 'Closed ends add a longitudinal stress to the wall, which changes the von Mises result.', fig: 'choice' },
    Sy: { what: 'The minimum yield strength of the cylinder wall material, from the material certificate or specification. The von Mises stress at the bore is compared with it.', tip: 'Use the specified minimum at the operating temperature, not a typical value.', fig: 'stress', sym: 'Sy' },
    req: { what: 'The minimum ratio of yield strength to von Mises stress the wall must achieve, from your design code, customer specification or company standard.', tip: 'Pressure equipment must follow its design code, which sets its own allowable stresses.', fig: 'factor', sym: 'n' },
  },
  'goodman-fatigue': {
    sa: { what: 'The alternating stress amplitude: half the difference between the maximum and minimum stress in each load cycle.', tip: 'Enter half the range, not the full range, and include the fatigue stress concentration factor Kf.', effect: 'A higher amplitude lowers every fatigue safety factor.', fig: 'stress', sym: 'σa' },
    sm: { what: 'The mean stress: the average of the maximum and minimum stress in each load cycle. Tension is positive.', tip: 'When the mean stress is zero or compressive, the tool uses the alternating stress alone for fatigue.', fig: 'stress', sym: 'σm' },
    Se: { what: 'The endurance limit of the part, corrected for surface finish, size, load type, temperature and reliability: the alternating stress it can take indefinitely with no mean stress.', tip: 'Use the corrected value for the actual part, not the plain test-specimen value; the result depends strongly on it.', fig: 'stress', sym: 'Se' },
    Su: { what: 'The ultimate tensile strength of the material, the highest stress it reaches in a tensile test, from the material certificate. It is used by the Goodman and Gerber lines.', tip: 'Use the certified or specified minimum, not a typical value.', fig: 'stress', sym: 'Su' },
    Sy: { what: 'The minimum yield strength of the material, from the material certificate or specification. It is used for the Soderberg line and the first-cycle yield check.', tip: 'Use the specified minimum, not a typical value.', fig: 'stress', sym: 'Sy' },
    req: { what: 'The minimum fatigue safety factor the part must achieve, from your design code, customer specification or company standard. It is compared with the lower of the Goodman and yield factors.', tip: 'This is a requirement you set; the tool only compares the calculated factor with it.', fig: 'factor', sym: 'n' },
  },
  'beam-cases': {
    case: { what: 'The support and loading arrangement of the beam. It decides the formulas for reactions, maximum moment and deflection.', tip: 'Real supports are rarely perfectly fixed; a fixed-end case gives lower moments and deflections than a partly fixed beam.', fig: 'choice' },
    load: { what: 'The load on the beam: a single point load, or for the uniform-load cases the total of the distributed load over the whole span.', tip: 'For a uniform load enter the total, which is the load per millimetre times the span, not the load per unit length.', effect: 'Moment, stress and deflection all rise in proportion to the load.', fig: 'force', sym: 'P' },
    L: { what: 'The span of the beam between its supports, or the projecting length of a cantilever from its fixed end.', tip: 'Use the distance between the support centres or bearing points.', effect: 'Deflection rises with the cube of the span for the same total load.', fig: 'length', sym: 'L' },
    a: { what: 'The distance from the left support to the point load. Used only for the simply supported off-centre case.', tip: 'It must lie between the two supports; it is ignored for the other cases.', fig: 'length', sym: 'a' },
    E: { what: 'The elastic modulus (Young’s modulus) of the beam material, from the material data sheet. It sets how far the beam deflects.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', effect: 'Deflection falls in proportion as the modulus rises; stress is unaffected.', fig: 'modulus', sym: 'E' },
    I: { what: 'The second moment of area of the beam section about the axis it bends about, from a section table or section properties calculation.', tip: 'Use the value about the bending axis; for an I-beam on edge that is the strong axis.', effect: 'Deflection and stress both fall in proportion as it rises.', fig: 'section', sym: 'I' },
    c: { what: 'The distance from the neutral axis of the section to its outermost fibre, where bending stress is highest.', tip: 'For a symmetrical section it is half the depth; for an unsymmetrical one use the larger distance.', effect: 'Bending stress rises in proportion to it.', fig: 'length', sym: 'c' },
    allow: { what: 'The highest bending stress the beam is allowed to reach, from your design code or company standard. The calculated stress is compared with it.', tip: 'This is a design limit you supply, not the material’s yield strength unless your code says so.', fig: 'stress' },
  },
  'shaft-diameter': {
    M: { what: 'The largest bending moment at the shaft section being sized, read from the shaft’s bending moment diagram.', tip: 'Enter N·m, not N·mm. Combine moments in two planes as the square root of the sum of their squares first.', fig: 'torque', sym: 'M' },
    T: { what: 'The torque transmitted through the shaft at the section being sized, for example from motor power and speed.', tip: 'Enter N·m, not N·mm; use the torque that actually passes through this section.', fig: 'torque', sym: 'T' },
    Km: { what: 'A combined shock and fatigue factor that multiplies the bending moment, allowing for how suddenly and how often the bending load is applied.', tip: 'Take it from your design method or code for the type of loading; do not choose it to make a shaft pass.', fig: 'factor', sym: 'Km' },
    Kt: { what: 'A combined shock and fatigue factor that multiplies the torque, allowing for how suddenly and how often the torque is applied.', tip: 'Take it from your design method or code for the type of loading.', fig: 'factor', sym: 'Kt' },
    tau: { what: 'The allowable shear stress for the shaft material in your design method. The tool sizes the shaft so the combined stress does not exceed it.', tip: 'Enter the allowable before any keyway reduction; the keyway option applies the reduction.', effect: 'The required diameter varies with the inverse cube root of this stress.', fig: 'stress', sym: 'τ' },
    keyway: { what: 'Whether a keyway is cut at the section being sized. With a keyway the tool reduces the allowable shear stress to 0.75 of the entered value.', tip: 'Choose yes if any keyseat is at or near the section.', fig: 'choice' },
    d: { what: 'The diameter of an existing or proposed solid shaft at this section, to check its shear stress against the requirement. Zero skips the check.', tip: 'Use the smallest diameter at the section, for example at the bottom of a groove.', fig: 'diameter', sym: 'd' },
  },
  'critical-speed': {
    d: { what: 'The diameter of the solid shaft, assumed the same along the whole length between the supports.', tip: 'For a stepped shaft this simple model is approximate; use the diameter over most of the length.', effect: 'For the shaft alone the critical speed rises in proportion to the diameter.', fig: 'diameter', sym: 'd' },
    L: { what: 'The distance between the bearings, or for an overhung shaft the length from the fixed support to the free end.', tip: 'Measure between bearing centres.', effect: 'For the shaft alone the critical speed falls with the square of the length.', fig: 'length', sym: 'L' },
    E: { what: 'The elastic modulus (Young’s modulus) of the shaft material, from the material data sheet. It sets the bending stiffness.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'E' },
    rho: { what: 'The density of the shaft material: its mass per unit volume, from the material data sheet. It sets the shaft’s own mass.', tip: 'Enter kg/m³, not g/cm³: 1 g/cm³ is 1000 kg/m³.', fig: 'density', sym: 'ρ' },
    support: { what: 'How the bearings hold the shaft: simply supported (free to tilt) at both ends, fixed at one end and free at the other (overhung), or fixed at both ends.', tip: 'Real bearings lie between simple and fixed; choosing fixed gives a higher critical speed.', fig: 'choice' },
    disc: { what: 'The mass of a single pulley, rotor or disc carried at mid-span, or at the free end of an overhung shaft. Zero calculates the bare shaft only.', tip: 'Include hubs and fasteners of the disc. Several discs need a more detailed method.', fig: 'mass', sym: 'm' },
    rpm: { what: 'The highest speed the shaft runs at in service. The tool compares it with the critical speed.', tip: 'Include any overspeed or variable-speed range up to its top value.', fig: 'rotation', sym: 'n' },
    margin: { what: 'How far, as a percentage of the critical speed, the running speed must stay away from it on either side, from your design standard.', tip: 'Type the percentage itself (25 for 25 %), not a fraction.', fig: 'percent' },
  },
  'circular-plate': {
    edge: { what: 'How the edge of the round plate is held: clamped (built in, unable to rotate) or simply supported (resting, free to rotate).', tip: 'Real bolted or gasketed edges lie between the two; the simply supported case gives the larger stress and deflection.', fig: 'choice' },
    a: { what: 'The radius of the circle on which the plate is supported, from the centre to the support line such as the gasket or bolt circle.', tip: 'Enter the radius, not the diameter.', effect: 'Stress rises with the square of the radius and deflection with its fourth power.', fig: 'radius', sym: 'a' },
    t: { what: 'The thickness of the flat plate carrying the pressure.', tip: 'Use the minimum thickness after tolerance and any corrosion or machining allowance.', effect: 'Stress falls with the square of the thickness and deflection with its cube.', fig: 'thickness', sym: 't' },
    p: { what: 'The pressure difference across the plate, spread uniformly over its face, between the two sides.', tip: 'Enter MPa: 1 MPa is 10 bar. Use the difference between the two sides.', effect: 'Stress and deflection rise in proportion to the pressure.', fig: 'pressure', sym: 'p' },
    E: { what: 'The elastic modulus (Young’s modulus) of the plate material, from the material data sheet. It affects deflection, not stress.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'E' },
    nu: { what: 'Poisson’s ratio of the plate material: how much it contracts sideways when stretched, as a fraction, from the material data sheet.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'ν' },
    allow: { what: 'The highest bending stress the plate is allowed to reach, from your design code. The calculated maximum stress is compared with it.', tip: 'Pressure vessel heads and bolted flanges must follow their own code rules.', fig: 'stress' },
  },
  'press-fit': {
    d: { what: 'The nominal diameter at the fitted surface, where the shaft and hub bore meet.', tip: 'Use the nominal fit size, not the shaft or bore limit sizes.', fig: 'diameter', sym: 'd' },
    D: { what: 'The outside diameter of the hub around the fit: the outer boundary of the material that grips the shaft.', tip: 'It must be larger than the fit diameter; a thin hub gives low pressure and high hoop stress.', fig: 'diameter', sym: 'D' },
    di: { what: 'The bore of a hollow shaft at the fit. Zero means a solid shaft.', tip: 'It must be smaller than the fit diameter; a bore makes the shaft more flexible and lowers the contact pressure.', fig: 'diameter', sym: 'dᵢ' },
    delta: { what: 'The diametral interference: how much larger the shaft diameter is than the hub bore before assembly.', tip: 'Use the diameter difference, not the radial one. Run the minimum for holding capacity and the maximum for hub stress.', effect: 'Contact pressure, hub stress and holding torque rise in proportion to it.', fig: 'gap', sym: 'δ' },
    L: { what: 'The axial length over which the shaft and hub are actually in contact.', tip: 'Exclude chamfers, grooves and any part of the hub that overhangs the shaft.', effect: 'Holding torque and axial force rise in proportion to it.', fig: 'length', sym: 'L' },
    mu: { what: 'The coefficient of friction between the shaft and hub surfaces in the assembled fit, which turns contact pressure into holding force.', tip: 'Take it from tests or your design guide; assembly method, lubrication and surface finish change it.', effect: 'Holding torque and axial force rise in proportion to it.', fig: 'friction', sym: 'μ' },
    Eh: { what: 'The elastic modulus (Young’s modulus) of the hub material, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'Eh' },
    nuh: { what: 'Poisson’s ratio of the hub material, from the material data sheet.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'νh' },
    Es: { what: 'The elastic modulus (Young’s modulus) of the shaft material, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'Es' },
    nus: { what: 'Poisson’s ratio of the shaft material, from the material data sheet.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'νs' },
    Sy: { what: 'The minimum yield strength of the hub material, from the material certificate or specification. The hub’s von Mises stress at the bore is compared with it.', tip: 'Use the specified minimum, not a typical value.', fig: 'stress', sym: 'Sy' },
    req: { what: 'The minimum ratio of hub yield strength to hub von Mises stress the fit must achieve, from your design code, customer specification or company standard.', tip: 'This is a requirement you set; the tool only compares the calculated factor with it.', fig: 'factor', sym: 'n' },
    alpha: { what: 'The coefficient of linear thermal expansion of the hub material over the heating range, used to work out how much the hub must be heated to slide on.', tip: 'Enter µm/(m·K), which is the same number as ×10⁻⁶ per K.', effect: 'A higher coefficient lowers the heating temperature needed.', fig: 'expansion', sym: 'α' },
    clear: { what: 'The extra diametral clearance wanted between the heated hub bore and the shaft so the hub slides on freely before it cools.', tip: 'It is added to the interference when calculating the heating temperature.', fig: 'gap' },
  },
  'thermal-stress': {
    E: { what: 'The elastic modulus (Young’s modulus) of the member’s material, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', effect: 'The thermal stress rises in proportion to the modulus.', fig: 'modulus', sym: 'E' },
    alpha: { what: 'The coefficient of linear thermal expansion of the material: how much a unit length grows per degree of temperature rise, over the relevant temperature range.', tip: 'Enter µm/(m·K), which is the same number as ×10⁻⁶ per K.', effect: 'The thermal stress rises in proportion to it.', fig: 'expansion', sym: 'α' },
    dT: { what: 'The change in temperature from when the member was fixed in place to the condition being checked. Positive for heating, negative for cooling.', tip: 'Use the difference from the installation temperature, not the operating temperature itself.', effect: 'Stress rises in proportion; heating gives compression and cooling gives tension.', fig: 'temp-diff', sym: 'ΔT' },
    restraint: { what: 'How much of the free thermal expansion is prevented: 100 % when the ends cannot move at all, less when the supports let the member move partly.', tip: 'Type the percentage itself (100 for full restraint), not a fraction.', effect: 'The stress and restraint force rise in proportion to it.', fig: 'percent' },
    A: { what: 'The cross-section area of the member, used to turn the thermal stress into the force on its anchors or restraints.', tip: 'Use the actual area of material, in mm².', effect: 'The force on the restraints rises in proportion; the stress does not change.', fig: 'area', sym: 'A' },
    Sy: { what: 'The minimum yield strength of the member’s material, from the material certificate or specification. The thermal stress is compared with it.', tip: 'Use the value at the operating temperature if it differs from room temperature.', fig: 'stress', sym: 'Sy' },
  },
  'hertz-contact': {
    geom: { what: 'Whether the bodies touch at a point (balls or spheres) or along a line (rollers, cylinders or wheels on a flat track).', tip: 'The contact length input is used only for line contact.', fig: 'choice' },
    R1: { what: 'The radius of the convex body at the contact, for example the radius of a ball or roller.', tip: 'Enter the radius, not the diameter.', fig: 'radius', sym: 'R₁' },
    R2: { what: 'The radius of the mating body at the contact. Zero means a flat surface; a negative value means a concave seat or groove that wraps round body 1.', tip: 'A concave radius must be larger than the convex radius of body 1, or the tool rejects it.', fig: 'radius', sym: 'R₂' },
    F: { what: 'The total load pressing the two bodies together, at right angles to the contact surface.', tip: 'Use the load on this one contact, not the total load shared by several balls or rollers.', fig: 'force', sym: 'F' },
    L: { what: 'The length of the line of contact, normally the width of the roller or wheel that touches the track. Used only for line contact.', tip: 'Use the effective contact length excluding end chamfers; edge loading raises the real pressure.', fig: 'length', sym: 'L' },
    E1: { what: 'The elastic modulus (Young’s modulus) of body 1, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'E₁' },
    nu1: { what: 'Poisson’s ratio of body 1, from the material data sheet.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'ν₁' },
    E2: { what: 'The elastic modulus (Young’s modulus) of body 2, from the material data sheet.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', fig: 'modulus', sym: 'E₂' },
    nu2: { what: 'Poisson’s ratio of body 2, from the material data sheet.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'ν₂' },
    allow: { what: 'The highest contact pressure allowed for the material, its hardness and the number of load cycles, from your design data. The peak contact pressure is compared with it.', tip: 'Contact pressure limits are much higher than ordinary stress limits; take them from contact-fatigue data, not from yield strength.', fig: 'pressure' },
  },
  'compression-spring': {
    d: { what: 'The diameter of the round wire the spring is coiled from, measured with a micrometer or taken from the specification.', tip: 'Measure the wire itself, not the coil.', effect: 'The rate rises with the fourth power of the wire diameter, so small changes matter a lot.', fig: 'diameter', sym: 'd' },
    D: { what: 'The mean coil diameter: the diameter of the circle through the centre of the wire, equal to the outside diameter minus one wire diameter.', tip: 'Do not enter the outside or inside diameter; convert it to the mean first.', effect: 'The rate falls with the cube of the mean diameter.', fig: 'diameter', sym: 'D' },
    Na: { what: 'The number of active coils: the coils that are free to deflect, not counting closed or ground end coils that sit solid.', tip: 'Total coils and active coils differ; the end type sets how many extra coils the tool adds for the solid length.', effect: 'The rate falls in proportion as active coils increase.', fig: 'coils', sym: 'Na' },
    ends: { what: 'The form of the spring ends: closed (squared) or plain, each ground flat or not. It sets the total coil count and the solid length.', tip: 'Check the drawing or the spring itself; closed and ground ends are common for stable seating.', fig: 'choice' },
    G: { what: 'The shear modulus (modulus of rigidity) of the wire material, from the spring maker or material data.', tip: 'Enter GPa, not MPa. Use the shear modulus, not the elastic (Young’s) modulus.', effect: 'The rate rises in proportion to the shear modulus.', fig: 'modulus', sym: 'G' },
    L0: { what: 'The free length of the spring with no load on it, measured over the ends.', tip: 'Measure several springs if possible; free length varies with manufacture.', fig: 'length', sym: 'L₀' },
    Lw: { what: 'The length of the spring when installed at the working position under the maximum load.', tip: 'It must be shorter than the free length and longer than the solid length.', effect: 'A shorter working length means more deflection, so a higher load and stress.', fig: 'length', sym: 'Lw' },
    allow: { what: 'The highest shear stress the wire may reach for its material, size and duty (static or fatigue), from the spring maker or design data.', tip: 'Fatigue duty needs a lower allowable than static duty; use the maker’s value for your case.', fig: 'stress', sym: 'τ' },
    rho: { what: 'The density of the wire material, used to work out the active coil mass and the spring’s natural frequency.', tip: 'Enter kg/m³, not g/cm³: 1 g/cm³ is 1000 kg/m³.', fig: 'density', sym: 'ρ' },
  },
  'extension-spring': {
    d: { what: 'The diameter of the round wire the extension spring is coiled from, measured with a micrometer or taken from the specification.', tip: 'Measure the wire itself, not the coil.', effect: 'The rate rises with the fourth power of the wire diameter.', fig: 'diameter', sym: 'd' },
    D: { what: 'The mean coil diameter: the diameter of the circle through the centre of the wire, equal to the outside diameter minus one wire diameter.', tip: 'Do not enter the outside or inside diameter; convert it to the mean first.', effect: 'The rate falls with the cube of the mean diameter.', fig: 'diameter', sym: 'D' },
    Na: { what: 'The number of active body coils that stretch under load. Hooks or loops are not part of the body.', tip: 'Makers sometimes count hooks as about one extra coil; follow the convention of your spring’s maker.', effect: 'The rate falls in proportion as active coils increase.', fig: 'coils', sym: 'Na' },
    G: { what: 'The shear modulus (modulus of rigidity) of the wire material, from the spring maker or material data.', tip: 'Enter GPa, not MPa. Use the shear modulus, not the elastic (Young’s) modulus.', fig: 'modulus', sym: 'G' },
    Fi: { what: 'The initial tension wound into the spring: the load needed before the tightly wound coils start to separate.', tip: 'Take it from the maker’s data or a load test; the spring does not extend until this load is exceeded.', effect: 'It adds directly to the load at every extension.', fig: 'force', sym: 'Fᵢ' },
    x: { what: 'How far the spring body is stretched beyond its free length at the working position.', tip: 'Use the extension from free length, not the total stretched length.', effect: 'The load above the initial tension rises in proportion to the extension.', fig: 'length', sym: 'x' },
    allow: { what: 'The highest shear stress the spring body may reach for its material and duty, from the spring maker or design data.', tip: 'Hooks and loops usually fail first and are not checked here; confirm them with the maker.', fig: 'stress', sym: 'τ' },
  },
  'torsion-spring': {
    d: { what: 'The diameter of the round wire the torsion spring is coiled from, measured with a micrometer or taken from the specification.', tip: 'Measure the wire itself, not the coil.', effect: 'Bending stress falls with the cube of the wire diameter and deflection with its fourth power.', fig: 'diameter', sym: 'd' },
    D: { what: 'The mean coil diameter: the diameter of the circle through the centre of the wire, equal to the outside diameter minus one wire diameter.', tip: 'Do not enter the outside or inside diameter; convert it to the mean first.', effect: 'The angular deflection rises in proportion to the mean diameter.', fig: 'diameter', sym: 'D' },
    Nb: { what: 'The number of body turns in the coil, not counting the straight legs.', tip: 'Count turns of the body only; leg deflection is not included in the result.', effect: 'The angular deflection rises in proportion to the body turns.', fig: 'coils', sym: 'Nb' },
    E: { what: 'The elastic (Young’s) modulus of the wire material, because a torsion spring’s wire works in bending. From the spring maker or material data.', tip: 'Enter GPa. Use the elastic modulus, not the shear modulus used for compression springs.', fig: 'modulus', sym: 'E' },
    F: { what: 'The force applied at the end of the spring arm, at right angles to the arm, that winds the spring.', tip: 'The load should wind the coils tighter; an unwinding load raises the stress beyond this model.', effect: 'Moment, deflection and stress all rise in proportion to the force.', fig: 'force', sym: 'F' },
    arm: { what: 'The moment arm: the perpendicular distance from the line of the applied force to the coil axis.', tip: 'Measure to the coil axis, not to the edge of the coil.', effect: 'Moment, deflection and stress all rise in proportion to the arm.', fig: 'length', sym: 'r' },
    arbor: { what: 'The diameter of the pin or arbor the spring fits over. As the spring winds up its inside diameter shrinks, and the tool checks it still clears the arbor. Zero skips the check.', tip: 'Measure the actual pin; the tool wants a 10 % clearance between the wound inside diameter and the arbor.', fig: 'diameter' },
    allow: { what: 'The highest bending stress the wire may reach for its material and duty, from the spring maker or design data.', tip: 'Fatigue duty needs a lower allowable than static duty; use the maker’s value for your case.', fig: 'stress', sym: 'σ' },
  },
  'spring-combination': {
    arr: { what: 'How the springs are connected: in parallel they sit side by side and share the load with the same deflection; in series one pushes on the next, so each carries the full load and the deflections add.', tip: 'Nested springs on the same seat act in parallel.', fig: 'choice' },
    k1: { what: 'The rate of the first spring: the force needed to deflect it by one millimetre, from its data sheet or a load test.', tip: 'Enter N/mm; a rate quoted in N/m must be divided by 1000.', fig: 'stiffness', sym: 'k₁' },
    k2: { what: 'The rate of the second spring: the force needed to deflect it by one millimetre, from its data sheet or a load test.', tip: 'Enter N/mm; a rate quoted in N/m must be divided by 1000.', fig: 'stiffness', sym: 'k₂' },
    k3: { what: 'The rate of an optional third spring in the combination, from its data sheet or a load test. Zero leaves it out.', tip: 'Leave it at 0 if there are only two springs.', fig: 'stiffness', sym: 'k₃' },
    k4: { what: 'The rate of an optional fourth spring in the combination, from its data sheet or a load test. Zero leaves it out.', tip: 'Leave it at 0 if there are fewer than four springs.', fig: 'stiffness', sym: 'k₄' },
    F: { what: 'The total load applied to the whole spring combination.', tip: 'Check each spring’s share of load and deflection against its own rating afterwards.', effect: 'Total deflection rises in proportion to the load.', fig: 'force', sym: 'F' },
  },
  'disc-spring': {
    De: { what: 'The outside diameter of the disc (Belleville) spring, from the catalogue or drawing.', tip: 'It must be larger than the inside diameter.', fig: 'diameter', sym: 'De' },
    Di: { what: 'The inside (bore) diameter of the disc spring, from the catalogue or drawing.', tip: 'It must be smaller than the outside diameter.', fig: 'diameter', sym: 'Di' },
    t: { what: 'The thickness of the disc spring material.', tip: 'Use the catalogue thickness; for discs with contact flats this model does not apply.', effect: 'The force rises steeply with thickness.', fig: 'thickness', sym: 't' },
    h0: { what: 'The free cone height of one disc: its unloaded overall height minus the material thickness. It is how far the disc can deflect before it is flat.', tip: 'Do not enter the overall free height; subtract the thickness first.', fig: 'height', sym: 'h₀' },
    E: { what: 'The elastic modulus (Young’s modulus) of the disc spring steel, from the maker or material data.', tip: 'Enter GPa, not MPa: 1 GPa is 1000 MPa.', effect: 'Force and stress rise in proportion to it.', fig: 'modulus', sym: 'E' },
    nu: { what: 'Poisson’s ratio of the disc spring material, from the maker or material data.', tip: 'It is a dimensionless ratio, not a percentage.', fig: 'number', sym: 'ν' },
    s: { what: 'How far one single disc is compressed at the working position, measured from its free height.', tip: 'Enter the deflection of one disc, not of the whole stack; it cannot exceed the free cone height.', fig: 'length', sym: 's' },
    ns: { what: 'The number of single discs, or nested sets, stacked face to face in alternating directions. Their deflections add.', tip: 'It multiplies the stack travel, not the force.', effect: 'Stack travel rises in proportion; force is unchanged.', fig: 'count', sym: 'nₛ' },
    np: { what: 'The number of discs nested in the same direction within each set. Their forces add.', tip: 'Friction between nested discs is ignored, so the real loading force is higher and the unloading force lower.', effect: 'The stack force rises in proportion; travel is unchanged.', fig: 'count', sym: 'nₚ' },
  },
});
